import json,pathlib,hashlib,datetime
D=pathlib.Path(__file__).resolve().parents[1]
X=json.loads((D/'extracted.json').read_text())
rec=[json.loads(l) for l in (D/'sources/receipts.jsonl').read_text().splitlines() if l.strip()]
rcp={r['url']:{k:r.get(k) for k in ('status','sha256','bytes','file','utc','error')} for r in rec}
def R(*arx): return {u:rcp[u] for a in arx for u in (f'https://arxiv.org/abs/{a}',f'https://arxiv.org/pdf/{a}') if u in rcp}
